package com.srent.ekyc;
import com.srent.common.BaseEntity; import com.srent.user.User; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="landlord_verifications") @Getter @Setter @NoArgsConstructor
public class LandlordVerification extends BaseEntity { public enum Status{SUBMITTED,AI_PROCESSED,NEEDS_REVIEW,APPROVED,REJECTED} @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="landlord_id",nullable=false) private User landlord; @Column(name="legal_name",nullable=false) private String legalName; @Column(name="identity_number_masked",nullable=false) private String identityNumberMasked; @Column(nullable=false) private String address; @Enumerated(EnumType.STRING) @Column(nullable=false) private Status status=Status.SUBMITTED; @Column(nullable=false) private String provider; @Column(nullable=false) private boolean simulated; @Column(name="extracted_data") private String extractedData; @Column(name="anomaly_reasons") private String anomalyReasons; @Column(name="admin_note") private String adminNote; }
